    }
    if let ciImage = self.mForegroundImage {
      let rImage = ciImage.extent
      let bp = NSBezierPath (rect: rImage).transformed (by: self.mForegroundImageAffineTransform)
      r = r.unioning (bp.bounds.canariRect)
    }
    return r
  }

